/**
 * Move admin-only chunks out of the public Vite output and into a server
 * module. Readers must not be able to download those files from the CDN.
 */
import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const publicDir = path.join(root, "dist", "public");
const adminDir = path.join(publicDir, "assets", "admin");
// dist/ is gitignored. The tracked stub at server/generated/adminChunks.ts stays
// empty; the production bundle aliases this generated file in its place.
const outFile = path.join(root, "dist", "generated", "adminChunks.ts");

const chunks = {};

if (fs.existsSync(adminDir)) {
  for (const file of fs.readdirSync(adminDir)) {
    if (!file.endsWith(".js") && !file.endsWith(".css")) continue;
    const full = path.join(adminDir, file);
    chunks[file] = fs.readFileSync(full);
    fs.unlinkSync(full);
  }
  fs.rmSync(adminDir, { recursive: true, force: true });
}

const requiredPrefixes = [
  "WritingStudio-",
  "Admin-",
  "AdminDashboard-",
  "AdminAIStudio-",
  "AdminAIUsage-",
  "AdminAudioGenerator-",
  "AdminCommandCenter-",
  "AdminQA-",
  "AdminLinks-",
  "AdminBooks-",
  "AdminReports-",
  "AdminStripeAnalytics-",
  "AdminEmailTemplates-",
  "AdminAffiliateAnalytics-",
  "AdminPartnerApplications-",
  "AdminSocialMediaKit-",
  "AdminSwitchy-",
  "AdminWebhooks-",
  "AdminTwilio-",
  "AdminSmsAnalytics-",
  "BlogEditor-",
  "NewsletterManager-",
  "NewsletterEditor-",
  "ExclusiveContentManager-",
];

const names = Object.keys(chunks);
const missing = requiredPrefixes.filter((prefix) => !names.some((name) => name.startsWith(prefix)));
if (names.length === 0 || missing.length > 0) {
  console.error("[seal-admin-chunks] Admin chunks were not all emitted under dist/public/assets/admin.");
  if (missing.length > 0) console.error(`[seal-admin-chunks] Missing: ${missing.join(", ")}`);
  console.error("[seal-admin-chunks] Refusing to leave admin tools in the public build.");
  process.exit(1);
}

fs.mkdirSync(path.dirname(outFile), { recursive: true });

const body = Object.entries(chunks)
  .map(([name, bytes]) => `  ${JSON.stringify(name)}: ${JSON.stringify(bytes.toString("utf8"))}`)
  .join(",\n");

fs.writeFileSync(
  outFile,
  `// Generated by scripts/seal-admin-chunks.mjs. Do not commit the sealed contents.\n` +
    `export const adminChunks: Record<string, string> = {\n${body},\n};\n`,
);

console.log(`[seal-admin-chunks] Sealed ${Object.keys(chunks).length} file(s): ${Object.keys(chunks).join(", ")}`);

const forbidden = [
  "AI Studio",
  "AI Chat",
  "AI Workflow",
  "ElevenLabs",
  "AI narration",
  "AI content",
  "ChatGPT",
  "Claude",
  "Yung-Lung",
  "Hudson Dynasty AI Workflow System",
  "Anti-AI Pass",
  "Powered by AI",
  "AI Trend Newsletter",
  "ai-assisted-romance-writing-workflow",
  "cutting-edge AI",
  // Unverifiable credentials and pen-name identity leaks (10/2026 audit).
  "USA Today",
  "USA TODAY",
  "finance VP",
  "Finance VP",
  "corporate VP",
  "Corporate VP",
  "corporate identity",
  "HSBC",
  // Retired Hudson Dynasty canon.
  "RIVIERA",
  "Audit of the Heart",
];

function walk(dir) {
  const hits = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) hits.push(...walk(full));
    else if (/\.(js|css|html|txt|xml|json)$/.test(entry.name)) hits.push(full);
  }
  return hits;
}

const leaks = [];
for (const file of walk(publicDir)) {
  const text = fs.readFileSync(file, "utf8");
  for (const phrase of forbidden) {
    if (text.includes(phrase)) leaks.push(`${path.relative(root, file)}: ${phrase}`);
  }
}

if (leaks.length > 0) {
  console.error("[seal-admin-chunks] Public build still contains retired copy:");
  for (const leak of leaks) console.error(`  ${leak}`);
  process.exit(1);
}
